  'reason.newOnSide': 'The file is new on the {side}.',
  'reason.changedOnSide': 'The file changed on the {side}.',
  'reason.changedBothSame': 'The file changed on both sides to the same content.',
  'reason.changedBoth': 'The file changed on both sides.',
  'reason.deletedOnSide': 'The file was deleted on the {side}.',
