  'reason.renamedOnSide': 'The file was renamed on the {side}.',
  'reason.collision': 'The {side} side holds {names}, which the other side may not be able to tell apart. Rename one of them.',
  'reason.settling': 'The file changed on the {side} less than {period} ago. It waits until the file settles.',
  'reason.goneBoth': 'The file is gone on both sides, so its record is dropped.',
  'reason.appearedSame': 'The file appeared on both sides with the same content.',
  'reason.appearedDiffer': 'The file appeared on both sides with different content.',
  'reason.dirBoth': 'The folder is on both sides.',
  'reason.dirNewOnSide': 'The folder is new on the {side}.',
  'reason.dirRemovedOnSide': 'The folder was removed on the {side}.',
  'reason.dirGoneBoth': 'The folder is gone on both sides, so its record is dropped.',
  'reason.stepFailed': '{what} failed: {error}. The next run tries again.',
  'reason.removeDirFailed': 'The folder could not be removed: {error}. It stays where it is.',
  'reason.heldOpen': 'Another program holds the file open on the {side}. It waits until the file is closed.',
  'reason.heldOpenAdmin': 'Another program holds the file open on the {side}. Running as a service with administrator rights, ArrowLoop would copy it from a shadow copy.',
  'reason.snapshotFailed': 'Another program holds the file open on the {side}, and no shadow copy could be made to read it from: {error}.',
  'reason.unsupported': 'On the {side} there is {kind}, which this engine does not carry.',
  'reason.cloudOnly': '{what} failed because the file is only a placeholder of a cloud client, which could not download it: {error}. Keep the file on this device in the cloud client. The next run tries again.',
  'reason.sealed': 'The folder is locked on the {side}. OneDrive hands its Personal Vault to no app, so the folder is left out.',
  'reason.unreadable': 'The folder could not be read on the {side}, so this run leaves it alone on both sides.',
  'reason.vanished': 'The folder disappeared from the {side} while it was being read, so this run leaves it alone on both sides.',
  'reason.recordFailed': 'The record could not be written: {error}. The next run tries again.',
  'reason.conflictGone': 'One of the two versions is gone, so there is nothing left to decide.',
  'reason.heldOpenDuring': '{what} failed because another program held the file open: {error}. The next run tries again.',
  'reason.unverified': '{what} finished, but there is no checksum on the {side}, and this job insists on one. The next run tries again.',
  'reason.changedDuring': 'The file changed on the {side} while this run was going. The next run tries again.',
  'reason.inFlux': 'The file was being written on the {side} while it was copied, in {runs} runs in a row. It waits for the next run. {details}',
  'reason.oneWay': 'This job only copies what is on the {side} to the other side, so the version on the {side} stands.',
  'reason.takenBack': 'The version on the {side} is copied back, since a safety brake refused the change.',
