  'phone.appData': 'Android/data',
  'phone.appDataHint': 'Each folder in Android/data belongs to one app, and since Android 11 no other app may look inside, ArrowLoop included. On a rooted phone ArrowLoop reads and writes there; with Shizuku it can only read. With this switch on, the folders show up as a target called Android.',
