  'phone.doze': 'Background activity',
  'phone.dozeOff': 'Switch battery optimisation OFF for ArrowLoop. With it on, Android puts the app to sleep when the screen has been off for a while: a job set for the night then waits until you next pick the phone up, and a job in real time notices nothing until then.',
  'phone.charging': 'Only while charging',
  'phone.chargingHint': 'A timed run waits until the phone is on power. A run you start yourself goes ahead either way: pressing the button is a decision, and a program that argued with it would be wrong.',
