  // A one-way job's mode. Two of the three delete, so each hint says exactly
  // what it removes and what it leaves.
  'mode.label': 'Mode',
  'mode.sync': 'Copy only',
  'mode.syncHint': 'Everything the source has goes across. A file only the other side has is left exactly where it is, and nothing is ever removed for you.',
  'mode.mirror': 'Mirror',
  'mode.mirrorHint': 'The other side becomes an exact copy of the source, so a file the source does not have is deleted there. It goes into that side\'s trash first, and a run that would remove more than half of everything it knows about stops and says so.',
  'mode.move': 'Move',
  'mode.moveHint': 'A file goes across and then leaves the source, which is how a phone sends the camera up and gets the space back. The original goes into the trash rather than being destroyed, and it only leaves once the copy has actually landed.',
