  'new.change.buttonGlyphs': 'Every button has its own symbol, including the answers to a conflict and the update check, so {labels} applies to all of them.',
  'new.change.versionCard': 'Version numbers read without a v, and {check} shows a cloud that answers with a tick or an arrow.',
  'new.change.fdroidLogo': 'The F-Droid button shows the F-Droid logo in its own colours.',
  'new.change.trashBin': 'Everything that leads to {trash} shows a bin, the sidebar and the job menus too.',
  'new.change.labelPairs': 'On a phone the choices under {labels} stand two to a row, so their names fit.',
  'new.change.passkeyKey': 'Signing in with a passkey shows a key.',
  'new.change.welcomeMotion': 'On a new install the welcome page shows its three steps in the accent and plays them as a small scene: a pointer adds a target, sets up a job and runs the first sync.',
  'new.change.titleBar': 'The desktop app draws its own title bar on Windows and Linux, in the look you chose.',
  'new.change.unreadFolders': 'A folder ArrowLoop may not open, or one that disappears while it is being read, no longer stops the run. The run leaves it alone on both sides and names it in the run\'s details.',
  'new.change.settingsTiles': '{settings} is a column of tiles, and each tile shows all its cards. What {engine} held is now under {general}, {sync} and {safety}.',
  'new.change.anomaliesModule': 'A switch for {anomalies} on {safety} turns the notes and their page off. The brakes keep holding, and a held run is then answered on its job.',
  'new.change.infoTile': '{info} lists every version and checks them for updates. The {help} card adds the manual and a bug report.',
  'new.change.loginReset': 'A forgotten password can be reset from the login page with a code from the container log.',
  'new.change.notifyChannels': '{notifications} on {safety} also sends to email, Discord, Slack, Gotify, ntfy, an Apprise server and Healthchecks.io, each with its own switch and a test button.',
  'new.change.notifyTile': '{notifications} has a tile of its own in the settings.',
  'new.change.automationStart': 'Tasker, MacroDroid and other automation apps can start a job on the phone, or every job at once.',
  'new.change.trustedWifi': 'On the phone, a VPN can let its jobs connect directly on wifi networks you trust, such as the one at home.',
  'new.change.signIn': 'Sign in through Pocket ID or another sign-in service. Add one on the Security tile, and the sign-in page gets a button for it.',
  'new.change.apiTokens': 'API tokens for dashboards and scripts: one that reads the status and log, or one for everything. Your read tokens keep working.',
  'new.change.sessions': 'A sign-in lasts through restarts, and the Sessions card shows every signed-in browser so you can sign it out.',
  'new.change.passwordQuestion': 'If you signed in a while ago, ArrowLoop asks for your password before a sensitive change instead of signing you out.',
  'new.change.publicUrl': 'Passkeys and sign-in services need the address you open ArrowLoop at. Set it with ARROWLOOP_PUBLIC_URL.',
  'new.change.updateNow': 'Once a check finds a newer release, the desktop app updates right away from the Version card and restarts into the new version.',
  'new.change.phoneVpn': 'The phone app sets up a VPN too, and a job picks the tunnel it goes through, as on a server or the desktop app.',
  'new.change.phoneTolerance': 'A job in the phone app can set its own timestamp tolerance.',
  'new.change.internxtTwoFactor': 'Adding an Internxt target runs its own sign-in, and {test} asks for the {code} when the account has two-factor login on.',
  'new.change.onlyFiles': 'With {only}, a job syncs just the files that match its patterns.',
  'new.change.pauseAutomatic': '{pause} under {more} on {jobs} stops every automatic run until you resume.',
  'new.change.discordHelp': "The {help} card on {info} leads to ArrowLoop's own Discord server.",
  'new.change.trustCertificate': 'A WebDAV target whose server made its own certificate can trust it by its fingerprint.',
  'new.change.kdriveRoot': 'A kDrive target can start in your private folder, the shared one or any folder by its ID.',
  'new.change.hiddenFolders': 'In the folder picker, the switch {show} lists hidden folders too.',
  'new.change.tabletLandscape': 'On a tablet the phone app turns with the device, and its pages, the bottom bar and the panels that slide up keep to a column in the middle of the screen.',
  'new.change.tabletShell': 'On a tablet held sideways the phone app shows the side bar of the desktop and container versions, its settings as tiles and its lists across the whole width.',
  'new.change.trayMemory': 'In the notification area the desktop app closes its window and needs about a tenth of the memory, and the icon opens a fresh window in under a second.',
  'new.change.desktopCli': 'The desktop app takes the same commands as the command line. Its run-due command runs whatever is due and exits, so cron, Windows Task Scheduler or a systemd timer can keep your jobs on schedule without the app staying open.',
  'new.change.notifyTiles': '{add} shows every service as a tile with its logo, and a search finds one by name.',
  'new.change.notifyShoutrrr': 'A Shoutrrr channel sends straight from ArrowLoop to Telegram, Pushover, Teams and over twenty other services, and needs no server of its own.',
