  'job.brakesHint': 'A run that would delete or overwrite more than these shares of the job\'s files stops and waits for your answer. The brakes hold even with the anomaly notes switched off.',
  'trash.pruneHint': 'Removes only the entries older than the number of days you choose. Everything newer stays.',
  'conflict.why.changedBoth': 'Both sides changed this file since the last sync, so neither change could be carried across.',
  'conflict.why.appearedDiffer': 'This file turned up on both sides with different content before the two had ever been synced.',
