  'backup.confirm': 'Alle Aufträge und alle Einstellungen durch {file} ersetzen? Die bisherige Einrichtung ist dann weg, und sie kommt nur zurück, wenn du eine Kopie davon hast.',
  'autoBackup.title': 'Automatische Sicherungen',
  'autoBackup.hint': 'ArrowLoop legt selbst Kopien aller Aufträge und Einstellungen an: nach Plan und direkt bevor ein Import sie ersetzt. Eine neue Kopie entsteht nur, wenn sich etwas geändert hat, und die älteste geht, sobald es mehr sind, als du behältst.',
  'autoBackup.on': 'Automatisch sichern',
  'autoBackup.everyDays': 'Tage zwischen Sicherungen',
  'autoBackup.everyDaysHint': 'ArrowLoop schaut alle so viele Tage nach und legt eine Kopie an, wenn sich seit der letzten etwas geändert hat.',
  'autoBackup.at': 'Uhrzeit',
  'autoBackup.atHint': 'Die Sicherung entsteht zu dieser Uhrzeit, nach der Uhr des Geräts, auf dem ArrowLoop läuft. Ist das Gerät da gerade aus oder im Ruhezustand, holt ArrowLoop die Sicherung nach, sobald es wieder läuft.',
  'autoBackup.keep': 'Sicherungen behalten',
  'autoBackup.keepHint': 'Sind es mehr, wird die älteste entfernt. Dateien, die du selbst in den Ordner legst, bleiben unangetastet.',
  'autoBackup.folder': 'Sicherungsordner',
  'autoBackup.folderHint': 'Leer lassen für den Ordner backups neben den Einstellungen von ArrowLoop. Jede Kopie enthält deine Passwörter für Benachrichtigungen, genau wie ein Export, also nimm einen Ort, den nur du öffnen kannst.',
  'autoBackup.folderPhoneHint': 'Leer lassen, dann bleiben die Kopien in der App. Damit sie auch bleiben, wenn die App entfernt wird, wähl einen Ordner in Download oder Documents. Dafür braucht ArrowLoop Zugriff auf alle Dateien.',
