  'import.title': 'Aus {source} importieren',
  'import.confirm': 'Hinzufügen, was in {file} steht? Deine eigenen Aufträge und Ziele bleiben, wie sie sind. Die neuen Aufträge kommen pausiert an, so kannst du dir zuerst ihre Ordner ansehen und jeden fortsetzen, sobald er passt.',
