  'engine.foldCaseHint': '"Foto.jpg" und "foto.jpg" als dieselbe Datei behandeln. Einschalten, wenn eine Seite Windows oder ein Mac ist und die andere Linux, denn dort sind zwei Schreibweisen zwei Dateien.',
