  'engine.changePercent': 'Massenänderungs-Bremse',
  'engine.changePercentHint': 'Ein Lauf, der mehr als diesen Anteil aller bekannten Dateien überschreiben würde, hält den Auftrag an, statt es zu tun. So sieht ein Ordner aus, nachdem etwas seine Dateien verschlüsselt hat. Standard ist fünfzig, null schaltet die Bremse ab.',
  'anomaly.failingAfter': 'Gescheiterte Läufe in Folge',
  'anomaly.failingAfterHint': 'Nach so vielen gescheiterten Läufen in Folge bekommt ein Auftrag einen Hinweis. Null schaltet ihn ab.',
  'anomaly.overdueDays': 'Überfällig nach',
  'anomaly.overdueDaysHint': 'Gezählt ab dem geplanten Lauf, der ausgefallen ist, nicht ab dem letzten Lauf. Ein Auftrag, der einmal pro Woche läuft, ist erst überfällig, wenn sein wöchentlicher Lauf so viele Tage zu spät ist. Null schaltet den Hinweis ab.',
  'anomaly.daysLate': 'Tagen Verspätung',
  'anomaly.moduleHint': 'Hinweise zu Aufträgen, die immer wieder scheitern oder überfällig sind, und die Seite Anomalien. Ausgeschaltet hält eine Bremse einen Lauf trotzdem an, und der angehaltene Lauf wird bei seinem Auftrag beantwortet.',
  'anomaly.notifyHeld': 'Angehaltenen Auftrag melden',
  'anomaly.notifyHeldHint': 'Schickt eine Meldung, wenn eine Bremse einen Auftrag anhält: über die Benachrichtigungskanäle weiter unten und als Benachrichtigung auf diesem Gerät.',
  'anomaly.notifyNotes': 'Auch Hinweise melden',
  'anomaly.notifyNotesHint': 'Dieselbe Meldung für einen Auftrag, der wiederholt scheitert oder überfällig ist. Ohne sie steht ein Hinweis nur in der App.',
