  'targets.serverEmpty': 'Noch kein Server und keine Freigabe. Hier kommen SSH-Rechner über SFTP, WebDAV-Server und Windows-Freigaben dazu.',
  'targets.remoteName': 'Name',
  'targets.remoteNameHint': 'Wie dieser Speicher in ArrowLoop heißt. Leerzeichen, Bindestriche und alle anderen Zeichen gehen. Du kannst den Namen später ändern, und die Aufträge zeigen weiter auf denselben Speicher.',
