  'confirm.deleteRemote': 'Dieses Speicherziel löschen',
  'confirm.deleteRemoteStakes':
    'Die Einstellungen für {name} werden aus rclones Konfiguration entfernt, samt jedem Kennwort und jedem Schlüssel, der dort liegt. Vorher wird nichts irgendwohin kopiert, und es gibt kein Zurück: neu einrichten heißt, die Zugangsdaten neu zu tippen.',
  'targets.inUse': 'Aufträge verwenden dieses Ziel noch: {jobs}. Stell sie auf ein anderes Ziel um oder lösch sie, dann kannst du das Ziel löschen.',
  'targets.nameTaken': 'Ein anderes Ziel heißt schon {name}. Nimm einen anderen Namen, damit du die beiden auseinanderhältst.',
  'targets.nameNeeded': 'Gib dem Ziel zuerst einen Namen, damit du es in einem Auftrag wiederfindest.',
  'targets.hostKey': 'Serverschlüssel',
  'targets.hostKeyHint': 'ArrowLoop merkt sich diesen Schlüssel beim Speichern und lehnt den Server ab, falls er einmal einen anderen zeigt. Vergleich ihn mit dem Fingerabdruck, den dein Anbieter veröffentlicht.',
  'targets.certificate.untrusted': 'Unbekanntes Zertifikat',
  'targets.certificate.changed': 'Das Zertifikat hat sich geändert',
  'targets.certificate.untrustedHint': 'Keine bekannte Stelle bürgt für dieses Zertifikat. Das ist normal bei einem Server, der sich sein Zertifikat selbst ausgestellt hat. Vertrau ihm nur, wenn der Fingerabdruck mit dem übereinstimmt, den dein Server zeigt. Wenn du speicherst, nimmt ArrowLoop genau dieses Zertifikat für dieses Ziel an und fragt dich wieder, falls es sich einmal ändert.',
  'targets.certificate.changedHint': 'Das ist nicht das Zertifikat, dem du für dieses Ziel vertraust. Hast du dem Server ein neues Zertifikat gegeben, vergleich den Fingerabdruck und vertrau ihm. Hast du das nicht, hört vielleicht jemand mit. Dann vertrau ihm besser nicht.',
  'targets.certificate.trust': 'Diesem Zertifikat vertrauen',
  'targets.certificate.fingerprint': 'SHA-256-Fingerabdruck',
  'targets.certificate.subject': 'Ausgestellt für',
  'targets.certificate.issuer': 'Ausgestellt von',
  'targets.certificate.validUntil': 'Gültig bis',
  'targets.certificate.trusted': 'Vertrautes Zertifikat',
  'targets.certificate.trustedHint': 'ArrowLoop nimmt für dieses Ziel genau dieses Zertifikat an, obwohl keine bekannte Stelle dafür bürgt, und lehnt jedes andere ab. Wenn du ihm nicht mehr vertraust und speicherst, gilt wieder die übliche Prüfung.',
  'targets.certificate.remove': 'Nicht mehr vertrauen',
