  'about.title': 'Über',
  'about.body':
    'Ein einzelner Ritter, ein Feldzug: ansehnliche quelloffene Werkzeuge, die es in der Form, die ich wollte, nicht gab, gebaut, bis nichts mehr fehlt. Alles kostenlos, ohne Konten, ohne Telemetrie, ohne Werbung, ohne Bezahlstufen. Nirgends ein Sternchen. Nichts Lesbares verlässt je deine eigenen Mauern. An Abenden und Wochenenden geschmiedet, mit Herz und Dickkopf.',
  'about.coffee':
    'Wenn sich ArrowLoop einen Platz auf deinem Server oder Rechner verdient hat: wirf deinem Ritter eine Münze zu. Sie hilft, die Kosten zu decken, und hält das Projekt am Leben. Und sie lässt das Herz dieses Ritters etwas höher schlagen. Drei Wege stehen unten, nimm den, der dir passt.',
  'about.coffeeButton': 'Kaffee spendieren',
  'about.crypto': 'Krypto',
  'about.paypal': 'PayPal',
  'about.cryptoTitle': 'Mit Krypto spenden',
  'about.donateAppeal': 'Wirf deinem Ritter eine Münze zu: Sie deckt einen Teil der Kosten und hält das Projekt am Leben. Alles, was ich baue, kostet nichts und zeigt keine Werbung.',
  'about.cryptoIntro': 'Wähle eine Währung und ein Netzwerk, dann scanne den Code oder kopiere die Adresse.',
  'about.cryptoNetworks': 'Netzwerke',
  'about.cryptoNoTag': 'Kein Destination Tag und kein Memo nötig.',
  'about.coffeeIntro': 'Die Zahlung läuft direkt bei Buy Me a Coffee. Ein Konto brauchst du nicht.',
  'about.paypalIntro': 'Die Zahlung läuft direkt bei PayPal, mit deinem PayPal-Konto oder mit Karte ohne Konto.',
