  'edit.trash': 'Auf jeder Seite einen Papierkorb führen',
  'edit.trashHint': 'Wohin eine Datei geht, statt vernichtet zu werden. Gelöschte Dateien und die unterlegene Fassung eines Konflikts landen dort, ein falscher Lauf ist also durch Zurückschieben rückgängig zu machen. Ausgeschaltet ist eine Löschung endgültig.',
  'edit.newerWins': 'Bei einem Konflikt gewinnt die neuere Fassung',
  'edit.newerWinsHint': 'Hat sich eine Datei auf beiden Seiten geändert, ersetzt die zuletzt gespeicherte Fassung die andere, und die andere kommt in den Papierkorb. ArrowLoop richtet sich dabei nach den Uhren beider Seiten. Ausgeschaltet bleiben beide Fassungen, und du entscheidest auf der Seite Konflikte.',
  'edit.minAge': 'Erst übertragen, wenn älter als',
  'edit.minAgeHint': 'Eine Datei geht erst hinüber, wenn sie so alt ist, gerechnet ab ihrer letzten Änderung. Bis dahin bleibt sie, wo sie ist. So bleiben deine neuen Fotos noch eine Weile auf dem Telefon.',
