  'preview.young': 'Noch nicht alt genug: {count}',
  'new.change.minAge': '{option} lässt in einem einseitigen Auftrag eine Datei auf der Quelle, bis sie alt genug ist. So bleiben deine neuen Fotos noch eine Weile auf dem Telefon.',
