  'opt.user': 'Benutzername',
  'opt.pass': 'Passwort',
  'opt.host': 'Server',
  'opt.url': 'Adresse',
  'opt.urlHint': 'Die vollständige Adresse des Speichers, nicht nur der Name des Servers: der Pfad dahinter gehört dazu. Eine Cloud nennt ihn in ihren eigenen Einstellungen unter WebDAV.',
  'opt.userHint': 'Der Name, mit dem du dich anmeldest, nicht der Anzeigename und nicht die E-Mail. Ein App-Token wird mit genau diesem Namen benutzt.',
  'opt.passHint': 'Das Passwort dieses Kontos. Wo der Dienst App-Passwörter anbietet, ist eines davon sicherer: es lässt sich einzeln zurückziehen, ohne das Passwort zu ändern, das du überall sonst benutzt.',
  'opt.passCloudHint': 'Hier gehört ein App-Token hin, NICHT dein Anmeldepasswort. In der Cloud erzeugen (Nextcloud: Einstellungen, Sicherheit, App-Passwort erstellen. OpenCloud: Konto, App-Tokens. OxiCloud: Profil, App-Passwörter), ganz kopieren und auf ein Leerzeichen am Ende achten. OpenCloud lehnt das Anmeldepasswort grundsätzlich ab, und ein Token lässt sich einzeln widerrufen, falls das Telefon einmal wegkommt.',
  'opt.hostHint': 'Name oder IP des Rechners, ohne http:// und ohne Pfad, also fileserver oder 192.168.1.20. Die Freigabe oder der Ordner gehört nicht dazu.',
  'opt.portHint': 'Nur nötig, wenn der Dienst nicht auf seinem üblichen Port liegt. Leer gelassen nimmt er den Standard: 22 bei SFTP, 445 bei einer Freigabe, 21 bei FTP.',
  'opt.tokenHint': 'Der Token, den der Dienst für diese App ausgestellt hat. Er wird nur einmal angezeigt, beim Anlegen, also ganz kopieren und auf ein Leerzeichen am Ende achten.',
  'opt.accessKeyHint': 'Die Schlüssel-ID des Objektspeichers, die kürzere Hälfte des Paares. Sie benennt das Konto und ist für sich allein kein Geheimnis. MinIO und Garage zeigen sie beim Anlegen des Schlüssels.',
  'opt.secretKeyHint': 'Die geheime Hälfte des Paares, einmalig beim Anlegen angezeigt. Wer sie hat, hat denselben Zugriff wie du: ist sie weg, lege einen neuen Schlüssel an, statt den alten zu suchen.',
  'opt.endpointHint': 'Nur bei einem Speicher, der nicht Amazon ist: die Adresse deines eigenen Servers mit Port, zum Beispiel http://192.168.1.20:9000. Für Amazon selbst bleibt das Feld leer.',
  'opt.regionHint': 'Die Region, in der der Eimer liegt, so geschrieben wie der Speicher sie schreibt. Selbst betriebene Speicher nehmen meist jedes Wort, und us-east-1 ist die sichere Wahl, wenn ihre Einrichtung keine nennt.',
  'opt.port': 'Port',
  'opt.domain': 'Domäne',
  'opt.token': 'Anmelde-Token',
  'opt.vendor': 'Servertyp',
  'opt.provider': 'Anbieter',
  'opt.region': 'Region',
  'opt.bucket': 'Bucket',
  'opt.bucketHint': 'Nur für einen Schlüssel, der einen Bucket öffnen, die anderen aber nicht auflisten darf, etwa ein Cloudflare-R2-Objekt-Token. Test und Ordnerauswahl öffnen dann gleich diesen Bucket. Lass das Feld leer, um aus der Liste zu wählen.',
