  'help.authWhere': 'Du legst ihn an unter {url}',
  'help.authLogin': 'Derselbe Benutzername und dasselbe Passwort wie sonst auch. Es muss nichts vorher geholt werden.',
  'help.serverDefault': 'Der Server erwartet {value}, sofern seine eigenen Einstellungen nichts anderes nennen.',
  'help.authOauth': 'Dieser Dienst meldet sich über den Browser an, hier ist also nichts einzutragen.',
  'help.authApiKey': 'Ein API-Schlüssel, den du in den Einstellungen des Dienstes anlegst.',
  'help.authAccessKey': 'Ein Schlüsselpaar aus der Konsole des Dienstes. Die Schlüssel-ID ist öffentlich und steht in jeder Anleitung; das Geheimnis wird meist nur einmal angezeigt, beim Anlegen.',
  'help.authAppPassword': 'Nimm ein App-Passwort aus den Sicherheitseinstellungen deines Kontos, nicht dein Anmeldepasswort. Mit zweitem Faktor kann das Anmeldepasswort hier gar nicht funktionieren.',
