  // The phone: Android's own questions, which the container never asks.
  'phone.access': 'Dateizugriff',
  'phone.permissionHint': 'Diesen Schalter besitzt Android. Ein Tippen öffnet die Seite, auf der die Berechtigung erteilt oder entzogen wird.',
  'phone.accessNone': 'Diese Android-Version kennt die Berechtigung nicht, Ordner müssen also einzeln übergeben werden.',
  'phone.appData': 'Android/data',
  'phone.appDataHint': 'Jeder Ordner in Android/data gehört einer App, und seit Android 11 darf keine andere App hineinschauen, auch ArrowLoop nicht. Auf einem gerooteten Telefon liest und schreibt ArrowLoop dort, mit Shizuku kann es nur lesen. Ist der Schalter an, erscheinen die Ordner als Ziel namens Android.',
  'phone.appDataRoot': 'Über Root liest und schreibt ArrowLoop diese Ordner.',
  'phone.appDataShizuku': 'Über Shizuku liest ArrowLoop diese Ordner, ändern kann es sie nicht.',
  'phone.appDataNoWay': 'Dieses Telefon hat weder Root noch Shizuku, die Ordner bleiben also zu.',
  'phone.appDataStopped': 'Shizuku ist installiert, läuft aber nicht. Starte es in der Shizuku-App.',
  'phone.appDataDenied': 'Shizuku hat ArrowLoop den Zugriff noch nicht erlaubt.',
  'phone.appDataFailed': 'Der Zugriff auf die Ordner ist zweimal hintereinander abgebrochen. Schalte Android/data aus und wieder ein, um es noch einmal zu versuchen.',
  'phone.appDataAsk': 'Shizuku fragen',
  'phone.appDataWayRoot': 'Root',
  'phone.appDataNoSu': 'Unter diesem Namen antwortet kein su, Root geht also nicht.',
  'phone.appDataRootDenied': 'Dein Root-Manager hat ArrowLoop Root noch nicht erlaubt.',
  'phone.appDataNoShizuku': 'Shizuku ist nicht installiert.',
  'phone.appDataGetShizuku': 'Shizuku holen',
  'phone.appDataGetShizukuHint': 'Shizuku ist eine eigene App. Starte sie nach der Installation einmal über kabelloses Debugging oder Root und komm dann hierher zurück.',
  'phone.appDataRequestRoot': 'Root anfragen',
  'phone.appDataSu': 'su-Befehl',
  'phone.appDataSuHint': 'Manche Root-Manager benennen su um oder legen es woanders ab, und wenn ArrowLoop deshalb kein Root findet, trägst du hier den Namen oder Pfad ein.',
  'phone.appDataSuBad': 'Gib einen Befehlsnamen oder einen vollständigen Pfad ohne Leerzeichen ein.',
  'phone.sharedAdd': 'Ordner aus einer App hinzufügen',
  'phone.sharedAddHint': 'Manche Apps, etwa Tastaturen, zeigen ihre eigenen Ordner in der Dateiauswahl von Android. Wähl dort einen aus, dann kann ArrowLoop ihn ohne Root und ohne Shizuku synchronisieren. Die Ordner erscheinen im Ziel namens Apps. Entfernst du einen hier, verliert nur ArrowLoop den Zugriff, und die Dateien bleiben, wo sie sind.',
  'phone.sharedRemove': 'Entfernen',
  'phone.notify': 'Benachrichtigungen',
  'phone.doze': 'Hintergrundaktivität',
  'phone.dozeOff': 'Schalte die Akkuoptimierung für ArrowLoop AUS. Mit ihr legt Android die App schlafen, sobald der Bildschirm eine Weile aus war: ein Auftrag für die Nacht wartet dann, bis du das Telefon das nächste Mal in die Hand nimmst, und ein Auftrag in Echtzeit bemerkt bis dahin nichts.',
  'phone.charging': 'Nur beim Laden',
  'phone.chargingHint': 'Ein zeitgesteuerter Lauf wartet, bis das Telefon am Strom hängt. Ein Lauf, den du selbst startest, läuft trotzdem: den Knopf zu drücken ist eine Entscheidung, und ein Programm, das dagegen argumentiert, hätte unrecht.',
  'phone.wifi': 'Nur über WLAN',
  'phone.wifiHint': 'Ist das aus, synchronisiert er auch über Mobilfunk.',
  'sync.power': 'Akku und Ladung',
  'sync.network': 'Netzwerk',
  'phone.minBattery': 'Nicht unter dieser Ladung',
  'phone.minBatteryHint': 'In Prozent. Nur ohne Ladekabel: ein Telefon am Strom füllt sich ja. Leer heißt keine Grenze.',
  'phone.metered': 'Nicht über eine kostenpflichtige Verbindung',
  'phone.anomalyNotifyHeldHint': 'Meldet sich auf diesem Telefon, wenn eine Bremse einen Auftrag anhält.',
