  'info.rcloneHint': 'rclone ist ein Open-Source-Programm, das Dateien zwischen lokalen Laufwerken und über 70 Speicherdiensten kopiert und abgleicht, von Cloud-Laufwerken bis zu S3 und SFTP. ArrowLoop führt jeden Auftrag damit aus.',
