  'info.helpHint': 'Der Fehlerbericht ist eine Datei mit den Versionen, den Einstellungen und Aufträgen ohne Passwörter oder Schlüssel, den letzten 100 Läufen und den offenen Anomalien. Gesendet wird nichts: Du hängst sie selbst an ein Issue. Die Ausgabe deiner Befehle, die Namen deiner Dateien und der Name deines Benutzerordners bleiben auch draußen, damit sie in ein öffentliches Issue darf.',
