  'new.hint': 'Was die Updates gebracht haben, eine Karte je Release. Ein leuchtender Punkt markiert jede Änderung auf ihrer Seite, ein Klick darauf blendet ihn aus. Ein Punkt auf einem Link verschwindet, sobald alles dahinter gesehen ist.',
