  'new.where.navigation': 'Navigation',
  'new.where.jobPage': 'Die Seite eines Auftrags',
  'new.where.background': 'Im Hintergrund',
  'new.change.navigation': '{conflicts}, {anomalies} und {trash} haben einen eigenen Platz in der Navigation. {targets} ist in die {settings} gewandert, und ein Schalter dort holt es zurück.',
  'new.change.runStrip': 'Jeder Auftrag zeigt seine letzten 14 Läufe als Streifen und daneben einen Status.',
  'new.change.jobPage': 'Jeder Auftrag hat eine eigene Seite mit seinem Zustand, seinen Läufen und den Dateien, die er angefasst hat. Ausführen, Pausieren und Bearbeiten stehen oben in einer Reihe.',
  'new.change.listBar': '{filter} und {search} stehen in der Karte {history}, in der Zeile mit {files} und {runs}.',
  'new.change.settingsSearch': 'Die Suche über den Karten findet jede Einstellung, auch unter ihrem alten Namen. Drück / oder Strg+K.',
  'new.change.tileOrder': 'Die Kacheln unter {settings} lassen sich verschieben: eine gedrückt halten und ziehen, oder auf ihr Alt und eine Pfeiltaste drücken. {reset} unter {look} stellt die alte Reihenfolge wieder her.',
  'new.change.labelGlyphs': 'Jede Auswahl unter {labels} zeigt vor ihrem Namen ein Symbol.',
  'new.change.buttonGlyphs': 'Jeder Knopf hat sein eigenes Symbol, auch die Antworten auf einen Konflikt und die Update-Suche. So gilt {labels} für alle.',
  'new.change.versionCard': 'Versionsnummern stehen ohne v da, und {check} zeigt eine Wolke, die mit einem Haken oder einem Pfeil antwortet.',
  'new.change.fdroidLogo': 'Der F-Droid-Knopf zeigt das F-Droid-Logo in seinen eigenen Farben.',
  'new.change.trashBin': 'Jeder Weg zu {trash} zeigt einen Mülleimer, auch in der Seitenleiste und im Menü eines Auftrags.',
  'new.change.labelPairs': 'Auf dem Handy stehen die Auswahlen unter {labels} zu zweit in einer Reihe, damit ihre Namen passen.',
  'new.change.passkeyKey': 'Die Anmeldung mit einem Passkey zeigt einen Schlüssel.',
  'new.change.welcomeMotion': 'Bei einer neuen Installation zeigt die Willkommensseite ihre drei Schritte in der Akzentfarbe und spielt sie als kleine Szene vor: Ein Zeiger fügt ein Ziel hinzu, legt einen Auftrag an und startet den ersten Abgleich.',
  'new.change.titleBar': 'Die Desktop-App zeichnet unter Windows und Linux ihre eigene Titelleiste, im Aussehen, das du gewählt hast.',
  'new.change.unreadFolders': 'Ein Ordner, den ArrowLoop nicht öffnen darf oder der beim Lesen verschwindet, hält den Lauf nicht mehr auf. Der Lauf lässt ihn auf beiden Seiten in Ruhe und nennt ihn in den Details des Laufs.',
  'new.change.settingsTiles': 'Die {settings} sind eine Spalte aus Kacheln, und jede Kachel zeigt alle ihre Karten. Was unter {engine} stand, steht jetzt unter {general}, {sync} und {safety}.',
  'new.change.anomaliesModule': 'Ein Schalter für {anomalies} unter {safety} schaltet die Hinweise und ihre Seite ab. Die Bremsen halten weiter an, und ein angehaltener Lauf wird dann bei seinem Auftrag beantwortet.',
  'new.change.infoTile': '{info} listet jede Version und prüft sie auf Updates. Die Karte {help} hat das Handbuch und einen Fehlerbericht.',
  'new.change.loginReset': 'Ein vergessenes Passwort lässt sich auf der Anmeldeseite mit einem Code aus dem Container-Log zurücksetzen.',
  'new.change.notifyChannels': '{notifications} unter {safety} sendet jetzt auch per E-Mail, an Discord, Slack, Gotify, ntfy, einen Apprise-Server und Healthchecks.io, jeder Kanal mit eigenem Schalter und Testknopf.',
  'new.change.notifyTile': '{notifications} hat in den Einstellungen eine eigene Kachel.',
  'new.change.automationStart': 'Tasker, MacroDroid und andere Automatisierungs-Apps können auf dem Handy einen Auftrag starten oder alle auf einmal.',
  'new.change.trustedWifi': 'Am Handy lässt ein VPN seine Aufträge in deinen eigenen WLANs, etwa dem zu Hause, direkt verbinden.',
  'new.change.signIn': 'Melde dich über Pocket ID oder einen anderen Anmeldedienst an. Richte ihn in der Kachel Sicherheit ein, dann bekommt die Anmeldeseite einen Knopf dafür.',
  'new.change.apiTokens': 'API-Tokens für Dashboards und Skripte: eines, das Status und Log liest, oder eines für alles. Deine Lese-Tokens gehen weiter.',
  'new.change.sessions': 'Eine Anmeldung übersteht Neustarts, und die Karte Sitzungen zeigt jeden angemeldeten Browser, damit du ihn abmelden kannst.',
  'new.change.passwordQuestion': 'Liegt deine Anmeldung schon eine Weile zurück, fragt ArrowLoop vor einer heiklen Änderung nach deinem Passwort, statt dich abzumelden.',
  'new.change.publicUrl': 'Passkeys und Anmeldedienste brauchen die Adresse, unter der du ArrowLoop öffnest. Setze sie mit ARROWLOOP_PUBLIC_URL.',
  'new.change.updateNow': 'Hat eine Prüfung eine neuere Version gefunden, aktualisiert sich die Desktop-App direkt über die Karte Version und startet in der neuen Version neu.',
  'new.change.phoneVpn': 'Auch die Handy-App richtet jetzt ein VPN ein, und ein Auftrag wählt den Tunnel, durch den er geht, wie auf einem Server oder in der Desktop-App.',
  'new.change.phoneTolerance': 'Ein Auftrag in der Handy-App kann seine eigene Zeitstempel-Toleranz setzen.',
  'new.change.internxtTwoFactor': 'Beim Anlegen eines Internxt-Ziels läuft dessen eigene Anmeldung, und {test} fragt nach dem {code}, wenn das Konto die Zwei-Faktor-Anmeldung an hat.',
  'new.change.onlyFiles': 'Mit {only} gleicht ein Auftrag nur die Dateien ab, die zu seinen Mustern passen.',
  'new.change.pauseAutomatic': '{pause} unter {more} bei {jobs} hält jeden automatischen Lauf an, bis du fortsetzt.',
  'new.change.discordHelp': 'Die Karte {help} unter {info} führt zum eigenen Discord-Server von ArrowLoop.',
  'new.change.trustCertificate': 'Ein WebDAV-Ziel, dessen Server sein Zertifikat selbst erstellt hat, kann ihm über den Fingerabdruck vertrauen.',
  'new.change.kdriveRoot': 'Ein kDrive-Ziel kann in deinem privaten Ordner, im gemeinsamen oder in jedem Ordner per ID beginnen.',
  'new.change.hiddenFolders': 'In der Ordnerauswahl zeigt der Schalter {show} auch versteckte Ordner.',
  'new.change.tabletLandscape': 'Auf einem Tablet dreht sich die App mit dem Gerät, und ihre Seiten, die untere Leiste und die Fenster, die von unten hereinfahren, bleiben in einer Spalte in der Mitte des Bildschirms.',
  'new.change.tabletShell': 'Auf einem quer gehaltenen Tablet zeigt die App die Seitenleiste der Desktop- und Container-Version, die Einstellungen als Kacheln und die Listen über die ganze Breite.',
  'new.change.trayMemory': 'Im Infobereich schließt die Desktop-App ihr Fenster und braucht nur noch etwa ein Zehntel des Speichers, und das Symbol öffnet in unter einer Sekunde ein neues Fenster.',
  'new.change.desktopCli': 'Die Desktop-App versteht dieselben Befehle wie die Kommandozeile. Ihr Befehl run-due führt alles Fällige aus und beendet sich, so halten cron, die Windows-Aufgabenplanung oder ein systemd-Timer deine Aufträge im Takt, ohne dass die App offen bleiben muss.',
  'new.change.notifyTiles': '{add} zeigt jeden Dienst als Kachel mit seinem Logo, und die Suche findet ihn über den Namen.',
  'new.change.notifyShoutrrr': 'Ein Shoutrrr-Kanal schickt direkt aus ArrowLoop an Telegram, Pushover, Teams und über zwanzig weitere Dienste und braucht keinen eigenen Server.',
